import pandas as pd

def run(inputs: dict) -> dict:
    payments = inputs["payments"]

    clean_rows = []
    reject_rows = []

    valid_currencies = {"USD", "EUR", "GBP"}

    for _, row in payments.iterrows():
        payment_id = row["payment_id"]
        amount = row["amount"]
        currency = row["currency"]
        country = row["country"]

        reason_code = None

        if pd.isna(amount):
            reason_code = "AMT_NULL"
        elif amount <= 0:
            reason_code = "AMT_NONPOS"
        elif pd.isna(currency) or currency not in valid_currencies:
            reason_code = "CCY_INVALID"
        elif pd.isna(country):
            reason_code = "CTRY_NULL"

        if reason_code is None:
            clean_rows.append({
                "payment_id": payment_id,
                "amount": round(amount, 2),
                "currency": currency,
                "country": country,
            })
        else:
            reject_rows.append({
                "payment_id": payment_id,
                "amount": amount,
                "currency": currency,
                "country": country,
                "reason_code": reason_code,
            })

    payments_clean = pd.DataFrame(
        clean_rows,
        columns=["payment_id", "amount", "currency", "country"]
    )
    payments_rejects = pd.DataFrame(
        reject_rows,
        columns=["payment_id", "amount", "currency", "country", "reason_code"]
    )

    return {
        "payments_clean": payments_clean,
        "payments_rejects": payments_rejects,
    }
